  it('calls onError with coerced Error when provider rejects with a plain object (HALEngine#95)', async () => {
    let receivedError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        receivedError = error;
      },
    };

    const reason = {code: 503, detail: 'upstream down'};
    const orchestrator = createChatOrchestrator(
      {
        async *sendMessage(): AsyncGenerator<MessageChunk> {
          throw reason;
        },
        async generateStructured<T>(): Promise<T> {
          return {} as T;
        },
      } as AIProvider,
      promptBuilder,
      undefined,
      {hooks}
    );

    let thrown: unknown;
    try {
      await orchestrator.processMessage(createSession('hello'));
    } catch (e) {
      thrown = e;
    }

    expect(thrown).toBe(reason);
    expect(receivedError).toBeInstanceOf(Error);
    expect(receivedError?.message).toBe('[object Object]');
    // @ts-ignore
    expect(receivedError?.cause).toBe(reason);
  });
});
